#!/usr/bin/env python3\n\"\"\"\nStreaming Implementation Test\n\nThis script tests that the new streaming architecture works correctly:\n1. App.py detects streaming-capable handlers\n2. Disables progress spinner for streaming responses\n3. Enables real-time streaming output\n4. Falls back gracefully if streaming fails\n\"\"\"\n\nimport sys\nimport os\nsys.path.insert(0, '/Users/admin/Documents/DeepCoderX')\n\nfrom pathlib import Path\nfrom models.session import CommandContext\nfrom services.dual_model_handler import DualModelHandler\n\ndef test_streaming_detection():\n    \"\"\"Test that streaming detection works correctly.\"\"\"\n    print(\"=== STREAMING DETECTION TESTS ===\")\n    \n    try:\n        # Create test context\n        ctx = CommandContext(\n            user_input=\"test\",\n            root_path=Path.cwd(),\n            debug_mode=True\n        )\n        \n        # Create handler\n        handler = DualModelHandler(ctx, \"dual\")\n        \n        # Test cases for streaming detection\n        test_cases = [\n            (\"hello there, how are you doing today?\", \"conversation\", True),  # Should stream\n            (\"create a Python script for file sorting\", \"qwen_coder\", True),  # Should stream\n            (\"pwd\", \"conversation\", False),  # Should not stream (direct command)\n            (\"hi\", \"conversation\", False),  # Should not stream (too short)\n            (\"ls\", \"qwen_coder\", False),  # Should not stream (direct command)\n        ]\n        \n        print(f\"Testing {len(test_cases)} streaming detection cases...\")\n        \n        for i, (user_input, target, expected) in enumerate(test_cases, 1):\n            result = handler._should_stream_response(user_input, target)\n            status = \"✅ PASS\" if result == expected else \"❌ FAIL\"\n            print(f\"Test {i}: {status} - '{user_input}' -> {result} (expected {expected})\")\n            \n            if result != expected:\n                print(f\"  ERROR: Expected {expected}, got {result}\")\n                return False\n        \n        print(\"\\n✅ All streaming detection tests passed!\")\n        return True\n        \n    except Exception as e:\n        print(f\"❌ Streaming detection test failed: {e}\")\n        return False\n\ndef test_can_handle_logic():\n    \"\"\"Test that can_handle logic works for dual model handler.\"\"\"\n    print(\"\\n=== CAN_HANDLE LOGIC TESTS ===\")\n    \n    try:\n        # Create test context\n        ctx = CommandContext(\n            user_input=\"test input\",\n            root_path=Path.cwd(),\n            debug_mode=True\n        )\n        \n        # Create handler\n        handler = DualModelHandler(ctx, \"dual\")\n        \n        # Test can_handle logic\n        test_cases = [\n            (\"hello world\", True),  # Should handle (default provider)\n            (\"@dual create script\", True),  # Should handle (explicit dual)\n            (\"@semantic analyze this\", True),  # Should handle (explicit semantic)\n        ]\n        \n        print(f\"Testing {len(test_cases)} can_handle cases...\")\n        \n        for i, (user_input, expected) in enumerate(test_cases, 1):\n            handler.ctx.user_input = user_input\n            result = handler.can_handle()\n            status = \"✅ PASS\" if result == expected else \"❌ FAIL\"\n            print(f\"Test {i}: {status} - '{user_input}' -> {result} (expected {expected})\")\n            \n            if result != expected:\n                print(f\"  ERROR: Expected {expected}, got {result}\")\n                return False\n        \n        print(\"\\n✅ All can_handle tests passed!\")\n        return True\n        \n    except Exception as e:\n        print(f\"❌ Can_handle test failed: {e}\")\n        return False\n\ndef test_model_info():\n    \"\"\"Test that model info is accessible.\"\"\"\n    print(\"\\n=== MODEL INFO TESTS ===\")\n    \n    try:\n        # Create test context\n        ctx = CommandContext(\n            user_input=\"test\",\n            root_path=Path.cwd(),\n            debug_mode=True\n        )\n        \n        # Create handler\n        handler = DualModelHandler(ctx, \"dual\")\n        \n        # Get model info\n        info = handler.get_model_info()\n        \n        print(\"Model Information:\")\n        print(f\"  Semantic Parser: {info['semantic_parser']['name']}\")\n        print(f\"  Code Specialist: {info['code_specialist']['name']}\")\n        print(f\"  Total Memory: {info['total_memory']}\")\n        print(f\"  Specialist Loaded: {info['code_specialist']['loaded']}\")\n        \n        # Verify required fields\n        required_fields = ['semantic_parser', 'code_specialist', 'total_memory']\n        for field in required_fields:\n            if field not in info:\n                print(f\"❌ Missing required field: {field}\")\n                return False\n        \n        print(\"\\n✅ Model info test passed!\")\n        return True\n        \n    except Exception as e:\n        print(f\"❌ Model info test failed: {e}\")\n        return False\n\ndef main():\n    \"\"\"Run all streaming implementation tests.\"\"\"\n    print(\"🧪 STREAMING IMPLEMENTATION TESTS\")\n    print(\"Testing the new streaming architecture...\\n\")\n    \n    tests = [\n        test_streaming_detection,\n        test_can_handle_logic,\n        test_model_info\n    ]\n    \n    passed = 0\n    total = len(tests)\n    \n    for test in tests:\n        if test():\n            passed += 1\n        else:\n            print(\"\\n❌ Test failed, stopping execution\")\n            break\n    \n    print(f\"\\n📊 RESULTS: {passed}/{total} tests passed\")\n    \n    if passed == total:\n        print(\"\\n🎉 ALL TESTS PASSED! Streaming implementation is ready.\")\n        print(\"\\n📋 NEXT STEPS:\")\n        print(\"1. Test with actual DeepCoderX application\")\n        print(\"2. Try conversational inputs longer than 15 characters\")\n        print(\"3. Try code generation commands ('create a Python script')\")\n        print(\"4. Verify streaming output appears in real-time\")\n        print(\"5. Confirm no progress spinner during streaming\")\n    else:\n        print(\"\\n❌ SOME TESTS FAILED - streaming may not work correctly\")\n    \n    return passed == total\n\nif __name__ == \"__main__\":\n    success = main()\n    sys.exit(0 if success else 1)\n